using EddaStore.Data; using EddaStore.Models.Products; using EddaStore.Repositories.Interfaces; using Microsoft.EntityFrameworkCore;
namespace EddaStore.Repositories.Implementations;
public class ProductImageRepository(ApplicationDbContext context) : IProductImageRepository { public async Task<IReadOnlyList<ProductImage>> GetByProductIdAsync(Guid productId,CancellationToken ct=default)=>await context.ProductImages.AsNoTracking().Where(x=>x.ProductId==productId).OrderBy(x=>x.SortOrder).ToListAsync(ct); public Task<ProductImage?> GetAsync(Guid id,CancellationToken ct=default)=>context.ProductImages.FirstOrDefaultAsync(x=>x.Id==id,ct); public Task AddAsync(ProductImage image,CancellationToken ct=default)=>context.ProductImages.AddAsync(image,ct).AsTask(); public void Delete(ProductImage image)=>context.ProductImages.Remove(image); public async Task<bool> SaveChangesAsync(CancellationToken ct=default)=>await context.SaveChangesAsync(ct)>0; }
